const e = $input.first().json.body || {};
const p = e.payload || {};
const first = (name) => String(name || '').split(' ')[0] || 'candidate';
let m = null;
switch (e.event) {
  case 'candidate.created':
    if (['portal', 'email', 'n8n'].includes(p.source)) {
      m = { title: `Acknowledgement prepared for ${p.name}`,
            message: `To: ${p.email || '(no e-mail in the CV)'}\nDear ${first(p.name)},\n\nThank you for your application: we received your CV. A recruiter will answer you within ten working days. Your data is used only for this application and kept at most 24 months (candidate data policy KB-HR-004).\n\nThe recruiting team` };
    }
    break;
  case 'analysis.completed':
    if (p.grade >= 2) {
      m = { title: `Priority review: ${p.candidate_name} for ${p.job_title}`,
            message: `Grade ${p.grade}, score ${p.score}/100 (${p.method === 'llm' ? 'AI analysis' : 'fast estimate'}). Strong or partial fit: review it first (Human validation). Service level: shortlisted candidates are contacted within five working days.` };
    }
    break;
  case 'review.decided':
    if (p.decision === 'interview') {
      m = { title: `Interview invitation prepared for ${p.candidate_name}`,
            message: `Dear ${first(p.candidate_name)},\n\nFollowing your application for the ${p.job_title} position, we would be glad to meet you for an interview on ${p.interview_at}. The interview follows our structured format (KB-RR-004). Please confirm your availability.\n\nThe recruiting team` };
    } else if (p.decision === 'reject') {
      m = { title: `Answer prepared for ${p.candidate_name} (decision by ${p.reviewer})`,
            message: `Dear ${first(p.candidate_name)},\n\nThank you for your interest in the ${p.job_title} position. After a careful review by our recruiters, we will not continue with your application this time. You may ask for a human re-examination of your application, and for access to or deletion of your data, at any time (KB-HR-004).\n\nThe recruiting team\n\n(Recruiter's internal reason, not sent: ${p.notes || '—'})` };
    } else if (p.decision === 'shortlist') {
      m = { title: `Shortlisted: contact ${p.candidate_name} within five working days`,
            message: `${p.candidate_name} was shortlisted for ${p.job_title} by ${p.reviewer}. Schedule the interview within five working days (screening service levels, KB-RR-001).` };
    } else if (p.decision === 'hold') {
      m = { title: `On hold: ${p.candidate_name} for ${p.job_title}`,
            message: `Remember: every candidate receives an answer within ten working days of reception.` };
    }
    break;
  case 'test':
    m = { title: 'n8n is connected', message: 'The recruitment-events workflow received the test event from the app.' };
    break;
}
if (!m) return [];
return [{ json: { event: 'message.prepared', title: m.title, message: m.message,
                  payload: { from_event: e.event, ...p }, source: 'n8n' } }];
